// Picks through the physics library (code_physics): the polygons of the entities that can be picked are bodies in a world of the library,
// which finds the closest one with the bounding volume tree of the mesh of each, and not by looking at every triangle in the box of the line.
// What the library can not take (spheres, boxes, terrains, meshes that are moved by bones or whose matrix is sheared, ...) is picked by
// the runtime as before, and the closest of both is what is picked.

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <vector>

#include "collision_internal.hpp"
#include "environment.h"
#include "physics_library.hpp"
#include "scene_internal.hpp"

namespace bb::collision {
namespace {
	constexpr uint64_t obscure_bit = 1ull << 40;

	enum class state : uint8_t { none, legacy, body };

	struct record {
		state           mode = state::none;
		bool            kinematic = false; // The body was made to be moved, as its place changed once.
		bool            obscure = false;
		uint16_t        rebuilds = 0; // How often the mesh was made again: a mesh that changes all the time is not worth it.
		pick_signature  signature;
		bool            churn = false; // Its mesh changes all the time, so it is never given to the library.
		uint64_t        geometry = 0, geometry_of_mesh = 0;
		bp_mesh*        mesh = nullptr;
		bp_body         body = 0;
		buffer<int>     first_triangle; // Of each surface, as the mesh numbers them.
	};

	physics::api const* lib = nullptr;
	bp_world*           world = nullptr;
	buffer<record*>     records; // By entity number - 1.
	bool                tried = false, enabled = false;
	uint32_t            seen_entities = 0, seen_epoch = 0, seen_surfaces = 0; // What the bodies were last made from: nothing changed if all are the same.
	uint64_t            stat_syncs = 0, stat_meshes = 0, stat_adds = 0, stat_moves = 0, stat_casts = 0;
	constexpr uint32_t  min_triangles = 32; // Fewer are tested faster one by one than by asking the library.

	void drop_body(record& r)
	{
		if (r.body) {
			lib->body_remove(world, r.body);
			r.body = 0;
		}
	}

	void drop_mesh(record& r)
	{
		drop_body(r);
		if (r.mesh) {
			lib->mesh_destroy(r.mesh);
			r.mesh = nullptr;
		}
		r.first_triangle.clear();
	}

	uint64_t geometry_of(entity const& e)
	{
		uint64_t h = 1469598103934665603ull;
		auto     mix = [&](uint64_t v) { h = (h ^ v) * 1099511628211ull; };
		mix(e.surfaces.size);
		for (uint32_t s = 0; s < e.surfaces.size; s++) {
			surface const& surf = *e.surfaces[s];
			mix(reinterpret_cast<uintptr_t>(&surf));
			mix(surf.geometry_version);
			mix(surf.vertices.size);
			mix(surf.indices.size);
		}
		return h;
	}

	bool can_take(entity const& e)
	{
		if (e.terrain || !e.surfaces.size) {
			return false;
		}
		uint32_t triangles = 0;
		for (uint32_t s = 0; s < e.surfaces.size; s++) {
			if (e.surfaces[s]->skin) {
				return false; // The bones move its vertices.
			}
			triangles += e.surfaces[s]->indices.size / 3;
		}
		return triangles >= min_triangles;
	}

	bool make_mesh(entity const& e, record& r)
	{
		std::vector<float>    positions;
		std::vector<uint32_t> indices;
		r.first_triangle.clear();
		uint32_t base = 0;
		for (uint32_t s = 0; s < e.surfaces.size; s++) {
			surface const& surf = *e.surfaces[s];
			r.first_triangle.push(int(indices.size() / 3));
			for (uint32_t v = 0; v < surf.vertices.size; v++) {
				positions.push_back(surf.vertices[v].x);
				positions.push_back(surf.vertices[v].y);
				positions.push_back(surf.vertices[v].z);
			}
			for (uint32_t i = 0; i + 2 < surf.indices.size; i += 3) {
				for (uint32_t k = 0; k < 3; k++) {
					indices.push_back(surf.indices[i + k] + base);
				}
			}
			base += surf.vertices.size;
		}
		if (indices.empty()) {
			return false;
		}
		stat_meshes++;
		r.mesh = lib->mesh_create(positions.data(), uint32_t(positions.size() / 3), indices.data(), uint32_t(indices.size() / 3));
		return r.mesh != nullptr;
	}

	// The place, turn and scale of a matrix whose axes are square to each other. False if they are not (sheared), or the entity is mirrored or flat.
	bool decompose(const float* m, float position[3], float rotation[4], float scale[3])
	{
		vec3  axis[3] = { { m[0], m[1], m[2] }, { m[4], m[5], m[6] }, { m[8], m[9], m[10] } };
		float s[3];
		for (int k = 0; k < 3; k++) {
			s[k] = length(axis[k]);
			if (!(s[k] > 1e-6f) || !isfinite(s[k])) {
				return false;
			}
			axis[k] = axis[k] * (1.0f / s[k]);
		}
		if ((fabsf(dot(axis[0], axis[1])) > 1e-4f) || (fabsf(dot(axis[0], axis[2])) > 1e-4f) || (fabsf(dot(axis[1], axis[2])) > 1e-4f)) {
			return false;
		}
		if (!(dot(axis[0], cross(axis[1], axis[2])) > 0)) {
			return false;
		}
		// A rotation matrix with these columns, as a quaternion.
		float r00 = axis[0].x, r10 = axis[0].y, r20 = axis[0].z;
		float r01 = axis[1].x, r11 = axis[1].y, r21 = axis[1].z;
		float r02 = axis[2].x, r12 = axis[2].y, r22 = axis[2].z;
		float x, y, z, w;
		float trace = r00 + r11 + r22;
		if (trace > 0) {
			float t = sqrtf(trace + 1.0f) * 2;
			w = 0.25f * t;
			x = (r21 - r12) / t;
			y = (r02 - r20) / t;
			z = (r10 - r01) / t;
		} else if ((r00 > r11) && (r00 > r22)) {
			float t = sqrtf(1.0f + r00 - r11 - r22) * 2;
			w = (r21 - r12) / t;
			x = 0.25f * t;
			y = (r01 + r10) / t;
			z = (r02 + r20) / t;
		} else if (r11 > r22) {
			float t = sqrtf(1.0f + r11 - r00 - r22) * 2;
			w = (r02 - r20) / t;
			x = (r01 + r10) / t;
			y = 0.25f * t;
			z = (r12 + r21) / t;
		} else {
			float t = sqrtf(1.0f + r22 - r00 - r11) * 2;
			w = (r10 - r01) / t;
			x = (r02 + r20) / t;
			y = (r12 + r21) / t;
			z = 0.25f * t;
		}
		float n = sqrtf(x * x + y * y + z * z + w * w);
		rotation[0] = x / n;
		rotation[1] = y / n;
		rotation[2] = z / n;
		rotation[3] = w / n;
		position[0] = m[12];
		position[1] = m[13];
		position[2] = m[14];
		scale[0] = s[0];
		scale[1] = s[1];
		scale[2] = s[2];
		return true;
	}

	void update_entity(int handle, entity* e, record& r)
	{
		if (!e || (e->pick_mode != 2) || r.churn || !can_take(*e)) {
			if (!r.churn || !e) {
				drop_mesh(r);
				r.mode = state::none;
			}
			return;
		}
		pick_signature now;
		make_pick_signature(now, handle, e, false);
		if (now.deep) {
			drop_mesh(r);
			r.mode = state::none;
			return;
		}
		uint64_t geometry = geometry_of(*e);
		bool     obscure  = e->pick_obscure != 0;
		bool     same     = (memcmp(&now, &r.signature, sizeof(now)) == 0) && (geometry == r.geometry) && (obscure == r.obscure);
		if (same && (r.mode != state::none)) {
			return; // Nothing changed since it was looked at, whether it is a body or nothing for the library.
		}
		bool moved = (memcmp(&now, &r.signature, sizeof(now)) != 0);
		r.signature = now;
		r.geometry  = geometry;
		bool changed_mesh = (r.mesh != nullptr) && (geometry != r.geometry_of_mesh);
		if (!is_enabled(handle)) {
			drop_body(r); // The mesh stays for when it is shown again. Nothing is to be picked, as the runtime skips it too.
			r.obscure = obscure;
			r.mode    = state::body;
			return;
		}
		if (changed_mesh) {
			if (++r.rebuilds > 16) {
				drop_mesh(r);
				r.churn = true; // It changes all the time, so the runtime picks it.
				r.mode  = state::none;
				return;
			}
			drop_mesh(r);
		}
		if (!r.mesh) {
			if (!make_mesh(*e, r)) {
				r.mode = state::legacy;
				return;
			}
			r.geometry_of_mesh = geometry;
		}
		float m[16], position[3], rotation[4], scale[3];
		world_matrix(handle, m);
		if (!decompose(m, position, rotation, scale)) {
			drop_body(r);
			r.mode = state::legacy;
			return;
		}
		if (r.body && r.kinematic && (obscure == r.obscure)) {
			if (moved) {
				stat_moves++;
				lib->body_set_transform(world, r.body, position, rotation, scale);
			}
		} else {
			// A body that was there and has to change is moved from now on, which is cheaper than making it again every time.
			bool kinematic = (r.body != 0);
			drop_body(r);
			stat_adds++;
			r.body = lib->body_add_mesh(world, r.mesh, position, rotation, scale, uint64_t(handle) | (obscure ? obscure_bit : 0), kinematic ? 1 : 0);
			if (!r.body) {
				r.mode = state::legacy;
				return;
			}
			r.kinematic = kinematic;
		}
		r.obscure = obscure;
		r.mode    = state::body;
	}
} // namespace

bool pick_physics_begin()
{
	if (!tried) {
		tried = true;
		const char* backend = bb_env("BLITZLLVM_PICK_BACKEND");
		if (backend && (strcmp(backend, "jolt") == 0)) {
			lib = physics::library();
			if (lib) {
				world = lib->world_create(0);
			}
			enabled = (lib != nullptr) && (world != nullptr);
		}
	}
	if (!enabled) {
		return false;
	}
	uint32_t count = uint32_t(entity_count());
	// Whatever changes an entity says so (entity_moved), and whatever changes a mesh (surface_changed), so nothing is looked at while neither did.
	if ((count == seen_entities) && (entity_epoch == seen_epoch) && (surface_epoch == seen_surfaces)) {
		return true;
	}
	while (records.size < count) {
		records.push(nullptr);
	}
	for (uint32_t n = 0; n < count; n++) {
		int     handle = int(n) + 1;
		entity* e      = get_entity_raw(handle);
		record* r      = records[n];
		if (!r) {
			if (!e || (e->pick_mode != 2) || !can_take(*e)) {
				continue;
			}
			r = records[n] = new record();
		}
		update_entity(handle, e, *r);
	}
	stat_syncs++;
	seen_entities = count;
	seen_epoch    = entity_epoch;
	seen_surfaces = surface_epoch;
	return true;
}

void pick_physics_stats(FILE* f)
{
	fprintf(f, "physics enabled %d syncs %llu meshes %llu body adds %llu moves %llu casts %llu\n", enabled ? 1 : 0, (unsigned long long)stat_syncs, (unsigned long long)stat_meshes, (unsigned long long)stat_adds,
	        (unsigned long long)stat_moves, (unsigned long long)stat_casts);
}

bool pick_physics_serves(int handle)
{
	return enabled && (uint32_t(handle) - 1 < records.size) && records[uint32_t(handle) - 1] && (records[uint32_t(handle) - 1]->mode == state::body);
}

int pick_physics_cast(vec3 origin, vec3 direction, float radius, int ignore, int ignore2, bool only_obscuring, hit_info& hit)
{
	if (!(length(direction) > 1e-9f) || !isfinite(length(direction))) {
		return 0;
	}
	bp_cast  cast = {};
	uint64_t ignored[4];
	cast.origin[0]       = origin.x;
	cast.origin[1]       = origin.y;
	cast.origin[2]       = origin.z;
	cast.displacement[0] = direction.x;
	cast.displacement[1] = direction.y;
	cast.displacement[2] = direction.z;
	cast.radii[0] = cast.radii[1] = cast.radii[2] = radius;
	cast.front_faces_only = 1; // The picks of the original only hit a triangle that the line goes against...
	cast.ignore_overlaps  = 1; // ... and not one that the sphere has started inside of.
	// The user value of a body is the entity, and a bit for whether it obscures, so an entity is ignored with and without it.
	for (int entity : { ignore, ignore2 }) {
		if (entity) {
			ignored[cast.ignore_count++] = uint64_t(entity);
			ignored[cast.ignore_count++] = uint64_t(entity) | obscure_bit;
		}
	}
	cast.ignore = ignored;
	if (only_obscuring) {
		cast.user_mask  = obscure_bit;
		cast.user_value = obscure_bit;
	}
	stat_casts++;
	bp_hit result;
	lib->cast_closest(world, &cast, &result);
	if (!result.hit || !(result.fraction < hit.time)) {
		return 0;
	}
	int     handle = int(result.user & (obscure_bit - 1));
	record* r      = (uint32_t(handle) - 1 < records.size) ? records[uint32_t(handle) - 1] : nullptr;
	if (!r || (r->mode != state::body)) {
		return 0;
	}
	int surface = 0;
	for (uint32_t s = 0; s < r->first_triangle.size; s++) {
		if (int(result.triangle) >= r->first_triangle[s]) {
			surface = int(s);
		}
	}
	hit.time     = result.fraction;
	hit.normal   = { result.normal[0], result.normal[1], result.normal[2] };
	hit.surface  = surface + 1;
	hit.triangle = int(result.triangle) - r->first_triangle[uint32_t(surface)];
	return handle;
}
} // namespace bb::collision
